const { user_id, username, message, issue_type } = $json.body || {};

if (!message || !message.trim()) {
  return [{ json: { ok: false, error: 'message is required' } }];
}

const ticketId = `TKT-${Date.now().toString(36).toUpperCase()}`;
const issueType = issue_type || guessIssue(message);

function guessIssue(msg) {
  const m = msg.toLowerCase();
  if (/bug|error|crash|broken|not working|fail/i.test(m)) return 'bug';
  if (/help|how.to|what.is|how do|guide|tutorial|documentation/i.test(m)) return 'question';
  if (/reset|password|login|account|2fa|ban/i.test(m)) return 'account';
  if (/feature|request|suggest|would like|wish|idea/i.test(m)) return 'feature';
  if (/slow|lag|timeout|latency/i.test(m)) return 'performance';
  if (/pay|billing|plan|premium|subscrib|price|upgrade/i.test(m)) return 'billing';
  return 'other';
}

return [{ json: {
  ticketId,
  userId: user_id || 'anon',
  username: username || 'unknown',
  message: message.trim(),
  issueType,
  status: 'open',
  receivedAt: new Date().toISOString()
}}];

const faq = $('Format FAQ').item.json.faqData || '';
const term = ($fromAI('searchTerm', 'term', 'string') || '').toLowerCase();
const sections = faq.split(/\n## /);
const matches = sections.filter(s => s.toLowerCase().includes(term));
return [{ json: { results: matches.slice(0, 3).join('\n\n') || 'No matching FAQ entries found.' } }];

const type = $fromAI('type', 'type', 'string');
const title = $fromAI('title', 'title', 'string');
const desc = $fromAI('description', 'description', 'string');
// In production, POST to a Google Sheet or Notion DB
return [{ json: { logged: true, ticket: `TRACK-${Date.now().toString(36)}`, type, title } }];

const output = $json.output || '';
const needsEscalation = output.startsWith('[ESCALATE]') || /human|supervisor|manager|transfer|angry|threat/i.test(output);
return [{ json: { ...$json, needsEscalation, agentResponse: output.replace('[ESCALATE]', '').trim() } }];
